import math
fn puti(mut o &u8,x i64){bits:=u64(x);for k in 0..8{unsafe{o[k]=u8(bits&255)};bits>>=8}}
@[export:'naive_bayes']
pub fn naive_bayes(v &i64,n usize,o &u8,cap usize)i64{if isnil(v)||n<6{return -1};nr:=unsafe{v[0]};f:=unsafe{v[1]};if nr<2||nr>8||f<1||f>3||n!=usize(2+nr*(f+1)+f){return -1};mut labels:=[8]int{};mut order:=[3]i64{};mut counts:=[3]int{};mut cc:=0;mut x:=[8][3]f64{};mut p:=2;for r in 0..int(nr){lab:=unsafe{v[p]};p++;if lab<0||lab>2{return -1};mut c:=0;for c<cc&&order[c]!=lab{c++};if c==cc{order[cc]=lab;cc++};labels[r]=c;counts[c]++;for j in 0..int(f){z:=unsafe{v[p]};p++;if z < -10000||z>10000{return -1};x[r][j]=f64(z)/1000.0}};if cc<2{return -1};mut best:=f64(-1e300);mut ans:=order[0];for c in 0..cc{mut score:=math.log(f64(counts[c])/f64(nr));for j in 0..int(f){mut mean:=0.0;for r in 0..int(nr){if labels[r]==c{mean+=x[r][j]}};mean/=f64(counts[c]);mut variance:=0.0;for r in 0..int(nr){if labels[r]==c{d:=x[r][j]-mean;variance+=d*d}};variance=math.max(variance/f64(counts[c]),1e-9);raw:=unsafe{v[p+j]};if raw < -10000||raw>10000{return -1};q:=f64(raw)/1000.0;score+= -0.5*math.log(6.283185307179586*variance)-(q-mean)*(q-mean)/(2*variance)};if score>best{best=score;ans=order[c]}};if isnil(o)||cap<8{return -2};unsafe{puti(mut o,ans)};8}
